solutions.naive:
class Solution:
    def thirdMax(self, nums: list[int]) -> int:
        first = max(nums)
        prev = None
        cur = first
        for _ in range(3):
            cand = None
            for x in nums:
                if (prev is None or x < prev) and (cand is None or x > cand):
                    cand = x
            if cand is None:
                return first
            cur = prev = cand
        return cur

